// `kg` is the UI language code; keep `ky` as an alias for older saved settings.
translations.kg = translations.ky
translations.ky = translations.kg

// Make every locale safe to use for every page/card key. Missing copy falls
// back to Russian so a partial locale can never render a raw translation key.
const translationKeys = new Set(Object.keys(translations.ru ?? {}))
for (const dictionary of Object.values(translations)) {
  for (const key of Object.keys(dictionary)) translationKeys.add(key)
}
for (const dictionary of Object.values(translations)) {
  for (const key of translationKeys) {
    if (dictionary[key] == null || dictionary[key] === '') {
      dictionary[key] = translations.ru?.[key] ?? key
    }
  }
}

